(R/'main.js').write_text('''document.body.classList.add('js');
const register=document.getElementById('register');
const notes=[...document.querySelectorAll('.note')];
const rows=[...document.querySelectorAll('[data-select]')];
const contents=document.querySelector('.topic-list');
let selected='erp';let rememberedScroll=0;let lastFocus=null;
if(matchMedia('(max-width:950px)').matches)contents.open=false;
function mark(id){selected=id;rows.forEach(a=>{if(a.dataset.select===id)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current');});}
function route(){const hash=location.hash.slice(1);const note=notes.find(n=>n.id===hash);if(note){rememberedScroll=window.scrollY;lastFocus=document.activeElement;register.hidden=true;notes.forEach(n=>n.hidden=n!==note);document.body.classList.add('reading');mark(note.id.replace('note-',''));window.scrollTo(0,0);note.querySelector('h1').tabIndex=-1;note.querySelector('h1').focus({preventScroll:true});document.title=note.querySelector('h1').textContent+' / Victor Mendivil';}else{register.hidden=false;notes.forEach(n=>n.hidden=true);document.body.classList.remove('reading');const id=hash.replace('preview-','');if(rows.some(r=>r.dataset.select===id)){mark(id);requestAnimationFrame(()=>{const preview=document.getElementById('preview-'+id);preview.scrollIntoView({behavior:'instant'});const action=preview.querySelector('.open-note');action.focus({preventScroll:true});});}else{mark(selected);window.scrollTo(0,rememberedScroll);}document.title='Victor Mendivil / Open Register';}}
rows.forEach(row=>row.addEventListener('click',event=>{event.preventDefault();const id=row.dataset.select;mark(id);history.replaceState(null,'','#preview-'+id);if(register.hidden){register.hidden=false;notes.forEach(n=>n.hidden=true);document.body.classList.remove('reading');}document.getElementById('preview-'+id).scrollIntoView({behavior:'instant'});document.title='Victor Mendivil / Open Register';}));
window.addEventListener('hashchange',route);window.addEventListener('popstate',()=>{});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('reading')){location.hash='preview-'+selected;}else if(event.key==='Escape'&&contents.open){contents.open=false;contents.querySelector('summary').focus();}});
route();
''')
(R/'assets'/'PROVENANCE.json').write_text(json.dumps({'plates':[{'file':f'plate-{i}.svg','origin':'Original code-authored mathematical line artwork by Hermes for this local prototype','classification':'Illustrative exploration; not client work, equipment, portrait or shipped-product evidence'} for i in range(6)],'font':'Chivo, Google Fonts, SIL OFL; bundled license chivo-OFL.txt'},indent=2))
print('Built Open Register: six original SVG plates, six complete notes, independent Chivo and index routes.')
